@@ -1,2 +1,14 @@
 export const DEFAULT=3600000;
-export function parseTimeout(raw){const n=Number(raw);return Number.isSafeInteger(n)&&n>=60000&&n<=14400000?n:DEFAULT;}
+export function parseTimeout(raw){
+  let n;
+  if(typeof raw==='string'){
+    const t=raw.trim();
+    if(!/^\d+$/.test(t))return DEFAULT;
+    n=Number(t);
+  }else if(typeof raw==='number'){
+    n=raw;
+  }else{
+    return DEFAULT;
+  }
+  return Number.isSafeInteger(n)&&n>=60000&&n<=14400000?n:DEFAULT;
+}
